import io.agentscope.harness.agent.*;import io.agentscope.harness.agent.subagent.task.*;import io.agentscope.core.model.*;import io.agentscope.core.message.*;import io.agentscope.core.agent.*;import reactor.core.publisher.Flux;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;
public class GUsageProbe {public static void main(String[]a)throws Exception{AtomicInteger calls=new AtomicInteger();AtomicBoolean saw=new AtomicBoolean();Model m=new Model(){public String getModelName(){return "owned-no-network-stub";}public Flux<ChatResponse> stream(List<Msg> msgs,List<ToolSchema> schemas,GenerateOptions opts){int n=calls.incrementAndGet();if(n==1)return Flux.just(ChatResponse.builder().usage(new ChatUsage(10,5,0)).id("g-r1").content(List.of(ToolUseBlock.builder().id("g-wait").name("wait_async_results").input(Map.of("timeout_seconds",5,"task_ids","g-owned-task")).content("{\"timeout_seconds\":5,\"task_ids\":\"g-owned-task\"}").build())).finishReason("tool_calls").build());for(Msg msg:msgs)for(ContentBlock cb:msg.getContent())if(cb instanceof ToolResultBlock tr)for(ContentBlock out:tr.getOutput())if(out instanceof TextBlock text&&text.getText().contains("G-owned-background-result"))saw.set(true);return Flux.just(ChatResponse.builder().usage(new ChatUsage(10,5,0)).id("g-r2").content(List.of(TextBlock.builder().text("G-safe-finished").build())).finishReason("stop").build());}};var agent=HarnessAgent.builder().name("g-full-wait").model(m).workspace(Path.of(a[0])).maxIters(4).stateStore(new io.agentscope.core.state.InMemoryAgentStateStore()).build();RuntimeContext rc=RuntimeContext.builder().userId("g-synthetic-person").sessionId("g-owned-session-final-uuid").build();try{var task=agent.getTaskRepository().putTask(rc,"g-owned-task","g-owned-worker","g-owned-session-final-uuid",new TaskRunSpec.LocalTaskRunSpec(()->{try{Thread.sleep(1500);}catch(InterruptedException e){Thread.currentThread().interrupt();}return "G-owned-background-result";}));var events=agent.streamEvents(Msg.builder().role(MsgRole.USER).textContent("Synthetic wait test, no external work").build(),rc).collectList().block(java.time.Duration.ofSeconds(30));System.out.println("MODEL_STUB_CALLS="+calls.get());System.out.println("TASK_COMPLETED="+task.isCompleted());System.out.println("MODEL_RECEIVED_BACKGROUND_RESULT="+saw.get());long observed=events.stream().filter(e->e instanceof io.agentscope.core.event.ModelCallEndEvent).count();long in=events.stream().filter(e->e instanceof io.agentscope.core.event.ModelCallEndEvent).map(e->((io.agentscope.core.event.ModelCallEndEvent)e).getUsage()).filter(java.util.Objects::nonNull).mapToLong(ChatUsage::getInputTokens).sum();System.out.println("ALL_STUB_USAGE_INPUT="+(10*calls.get()));System.out.println("ALL_STUB_USAGE_OUTPUT="+(5*calls.get()));System.out.println("MODEL_END_EVENTS="+observed);System.out.println("BRIDGE_OBSERVABLE_INPUT="+in);System.out.println("STREAM_EVENTS_COUNT="+events.size());for(var ev:events)System.out.println("EVENT_TYPE="+ev.getType());if(!task.isCompleted()||!saw.get()||calls.get()<2)throw new AssertionError("wait stream result missing");}finally{agent.close();System.out.println("OWN_AGENT_CLOSE=RETURNED");}}}